import{_ as a,o as e,c as s,av as i}from"./chunks/framework.BPJ8Zp9i.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Hans API","text":"전국 병원 정보 API","tagline":"기관마다 흩어진 정부 병원 데이터를 하나로 합쳐, 검색 가능한 형태로 제공합니다.","actions":[{"theme":"brand","text":"병원 검색 API","link":"/apis/healthcare"},{"theme":"alt","text":"시작하기 (인증·다국어)","link":"/common"}]},"features":[{"title":"병원 검색","details":"지역·진료과목·종별·응급실 여부로 병원을 찾고, 진료시간·교통편·병상까지 상세로 받습니다.","link":"/apis/healthcare"},{"title":"참조 데이터","details":"검색 조건에 넣을 코드 목록입니다. 진료과목·종별·등급·장비·중증질환.","link":"/apis/healthcare-meta"},{"title":"다국어","details":"Accept-Language 헤더 하나로 한국어·영어·일본어 응답을 받습니다.","link":"/common#다국어"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function r(o,t,l,h,d,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h2 id="무엇을-하는-api-인가" tabindex="-1">무엇을 하는 API 인가 <a class="header-anchor" href="#무엇을-하는-api-인가" aria-label="Permalink to &quot;무엇을 하는 API 인가&quot;">​</a></h2><p>병원 정보는 정부 기관마다 흩어져 있습니다. <strong>건강보험심사평가원(HIRA)</strong> 은 병상·장비·진료과목 같은 기관 제원을 갖고 있고, <strong>국립중앙의료원(NMC)</strong> 은 진료시간과 응급실 운영 여부를 갖고 있습니다. 그런데 <strong>두 기관은 코드 체계도 기관 식별자도 다릅니다.</strong> 원본만으로는 &quot;우리 동네에서 지금 문 연 소아과&quot;를 찾을 수 없습니다.</p><p>Hans API 는 이 둘을 <strong>병원 단위로 매칭해 하나로 합친 것</strong>입니다. 원본을 주기적으로 동기화하고, 코드 체계를 통일하고, 검색할 수 있게 인덱싱합니다. 쓰는 쪽은 병원 하나를 가리키는 <strong>id 하나</strong>만 알면 됩니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 강남구의 응급실 운영 병원을 영어로</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer YOUR_API_KEY&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Accept-Language: en&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     &quot;https://api.plzhans.com/healthcare/hospitals?region=11680&amp;emergency=true&quot;</span></span></code></pre></div><h2 id="어디서부터-볼까" tabindex="-1">어디서부터 볼까 <a class="header-anchor" href="#어디서부터-볼까" aria-label="Permalink to &quot;어디서부터 볼까&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><a href="/develop/common.html"><strong>공통</strong></a></td><td>인증(<code>Authorization</code>)과 다국어(<code>Accept-Language</code>). <strong>모든 요청에 필요합니다.</strong></td></tr><tr><td><a href="/develop/apis/healthcare.html"><strong>병원 검색</strong></a></td><td>주력 API. 검색과 상세.</td></tr><tr><td><a href="/develop/apis/healthcare-meta.html"><strong>참조 데이터</strong></a></td><td>검색 조건에 넣을 코드. 드롭다운을 채울 때 씁니다.</td></tr><tr><td><a href="/develop/apis/region.html"><strong>주소</strong></a> · <a href="/develop/apis/transport.html"><strong>교통정보</strong></a></td><td>지역 코드, 지하철역 목록. 도메인 무관이라 병원 밖에서도 씁니다.</td></tr></tbody></table><h2 id="정부데이터-원본은-언제-쓰나" tabindex="-1">정부데이터 원본은 언제 쓰나 <a class="header-anchor" href="#정부데이터-원본은-언제-쓰나" aria-label="Permalink to &quot;정부데이터 원본은 언제 쓰나&quot;">​</a></h2><p><strong>대부분의 경우 쓸 일이 없습니다.</strong> HIRA·NMC 원본을 캐싱해 그대로 내주는 API 가 따로 있지만, 그건 원본의 코드 체계와 필드를 손대지 않고 노출합니다. 두 기관을 직접 매칭해 보고 싶거나, 통합 API 가 아직 내주지 않는 원본 필드가 필요할 때만 씁니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>원본 API 는 <strong>현재 공개돼 있으나 추후 허가받은 사용자로 제한될 예정</strong>입니다. 새로 붙이는 코드는 통합 API(<code>/healthcare/*</code>)를 쓰세요.</p></div>`,9)])])}const k=a(n,[["render",r]]);export{g as __pageData,k as default};
